body.script:
//
window.SYKA_BLOGGER_CONFIG={
  appBase:'https://cdn.jsdelivr.net/gh/taufx98/sykabelajar_3.0@gh-pages',
  supabaseUrl:'https://jrfogwueytiddnanetth.supabase.co',
  cloudinaryCloudName:'sykabelajar',
  cloudinaryUploadPreset:'sykabelajar_preset'
};
(function(){
  var root=document.getElementById('page-root');
  var path=window.location.pathname||'/';
  var known=['/login','/register','/home','/feed','/leaderboard','/awards','/notifications','/orders','/profile','/lomba','/organizer','/admin','/verify'];
  var shouldBridge=path!=='/'&&known.some(function(prefix){return path===prefix||path.indexOf(prefix+'/')===0;})&&window.location.hash.indexOf('#/')!==0;
  if(shouldBridge){window.location.replace(window.location.origin+'/#'+path+window.location.search);return;}
  function css(url){return new Promise(function(ok,no){var l=document.createElement('link');l.rel='stylesheet';l.href=url;l.onload=ok;l.onerror=no;document.head.appendChild(l);});}
  function js(url){return new Promise(function(ok,no){var s=document.createElement('script');s.type='module';s.src=url;s.onload=ok;s.onerror=function(){no(new Error('Gagal memuat '+url));};document.body.appendChild(s);});}
  Promise.all([css(window.SYKA_BLOGGER_CONFIG.appBase+'/styles.min.css?v=18'),js(window.SYKA_BLOGGER_CONFIG.appBase+'/app.js?v=18')]).catch(function(e){console.error('[SykaBelajar] bundle load failed',e);root.innerHTML='<div class="blogger-noscript"><strong>SykaBelajar sedang memuat ulang.</strong><br/>Bundle aplikasi belum berhasil dimuat. Refresh halaman atau periksa deployment gh-pages.</div>';});
})();
//
